"""Connection implementations."""

import dataclasses
import enum
import logging
import typing

from jsilib import _utils
from jsilib._compat import asyncio
from jsilib.aio import exc as aio_exc
from jsilib.aio.interface import IReactor, IStream
from jsilib.aio.streams import ByteStream

from . import _globals, exc
from .frames import Frame
from .interface import ITransportConnection

__all__ = export = _utils.ExportList()

logger = logging.getLogger(_globals.LOGGER_NAME)


@export
class TransportConnection(ITransportConnection):
    """Default, production-ready implementation of the
    :class:`ITransportConnection` interface.

    :param reactor:
        Reactor to be used

    :param stream:
        I/O stream to read/write frames from/to
    """

    def __init__(self, reactor: IReactor, stream: IStream):

        @_utils.log_exceptions(logger)
        async def frame_reader():
            while not stream.is_closed():
                try:
                    frame = await Frame.load(stream)
                    logger.debug('[%s] < %r', _utils.get_obj_addr(self), frame)
                    self._incoming_frame_queue.put_nowait(frame)
                except aio_exc.StreamClosedError:
                    self._incoming_frame_queue.put_nowait(None)
                    break

        @_utils.log_exceptions(logger)
        async def frame_writer():
            while not stream.is_closed():
                proxy = await self._outgoing_frame_queue.get()
                try:
                    buffer = ByteStream()
                    await proxy.frame.dump(buffer)
                    await stream.write(buffer.data)
                    logger.debug('[%s] > %r', _utils.get_obj_addr(self), proxy.frame)
                except aio_exc.StreamClosedError:
                    proxy.error = self._OutgoingFrameProxy.Error.STREAM_CLOSED
                    break
                finally:
                    proxy.sem.release()

        self._closed = False
        self._reactor = reactor
        self._incoming_frame_queue: asyncio.Queue[typing.Optional[Frame]] = asyncio.Queue()
        self._outgoing_frame_queue: asyncio.Queue[TransportConnection._OutgoingFrameProxy] = asyncio.Queue()
        self._frame_reader_task = reactor.run(frame_reader())
        self._frame_writer_task = reactor.run(frame_writer())
        self._stream = stream

    def is_closed(self) -> bool:
        return self._closed

    async def close(self):
        if self._closed:
            return
        self._closed = True
        logger.debug('[%s] Closing transport connection...', _utils.get_obj_addr(self))
        await self._frame_reader_task.cancel()
        await self._frame_writer_task.cancel()
        logger.debug('[%s] Transport connection closed.', _utils.get_obj_addr(self))

    async def recv(self) -> Frame:
        if self.is_closed():
            raise exc.ConnectionClosedError()
        frame = await self._incoming_frame_queue.get()
        if frame is None:
            raise exc.ConnectionClosedError()
        return frame

    def send_nowait(self, frame: Frame):

        async def send_nothrow(frame: Frame):
            try:
                await self.send(frame)
            except Exception:
                logger.warning("send_nowait() did not complete:", exc_info=True)

        if self.is_closed():
            raise exc.ConnectionClosedError()
        self._reactor.run(send_nothrow(frame))

    async def send(self, frame: Frame):
        if self.is_closed():
            raise exc.ConnectionClosedError()
        proxy = self._OutgoingFrameProxy(frame)
        self._outgoing_frame_queue.put_nowait(proxy)
        await proxy.sem.acquire()
        if proxy.error == self._OutgoingFrameProxy.Error.STREAM_CLOSED:
            raise exc.ConnectionClosedError()

    def get_write_buffer_size(self) -> int:
        if self.is_closed():
            return 0
        return self._stream.get_write_buffer_size()

    @dataclasses.dataclass
    class _OutgoingFrameProxy:

        class Error(enum.Enum):
            STREAM_CLOSED = 1

        frame: Frame
        sem: asyncio.Semaphore = dataclasses.field(default_factory=lambda: asyncio.Semaphore(0))
        error: typing.Optional[Error] = None


@export
class QueueTransportConnection(ITransportConnection):
    """Implementation of the :class:`ITransportConnection` interface, but based
    on input/output queues.

    This can be used to create a locally communicating transports, simply by
    creating two instances of this class and reversing the order of queues
    given to the constructor. This can be used as a handy helper for testing
    upper-level layers.

    :param input:
        Input queue (from where frames are read)

    :param output:
        Output queue (where frames are written)
    """
    _close_signal = object()

    def __init__(self, input: asyncio.Queue[Frame], output: asyncio.Queue[Frame]):
        self._input = input
        self._output = output
        self._closed = False

    def is_closed(self) -> bool:
        return self._closed

    async def close(self):
        if not self._closed:
            self._closed = True
            self._input.put_nowait(self._close_signal)

    async def recv(self) -> Frame:
        frame = await self._input.get()
        if frame is self._close_signal:
            raise exc.ConnectionClosedError()
        return frame

    def send_nowait(self, frame: Frame):
        if self._closed:
            raise exc.ConnectionClosedError()
        self._output.put_nowait(frame)

    async def send(self, frame: Frame):
        self.send_nowait(frame)

    # This method is not applicable for QueueTransportConnection,
    # but it is required by the interface.
    def get_write_buffer_size(self) -> int:
        return -1
